"""Independent saved-evidence review; no group analyzer import and no physics."""
from pathlib import Path
import hashlib,json
import numpy as np
ROOT=Path(__file__).resolve().parents[2];G=ROOT/'experiments/mujoco_joint_contact_lab/friction_low_regime'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def mx(a):return float(np.max(np.abs(a))) if np.size(a) else 0.
def main():
    p=read(G/'protocol.json');frozen=read(ROOT/'planning/mujoco-joint-contact-2026-10-29/friction_low_regime-freeze.json');design=read(ROOT/frozen['design_reference']);publication=read(G/'publication.json');analysis=read(G/'analysis.json');checks=[];measurements=[];arrays={};stats={}
    def ck(name,actual,expected,passed):checks.append({'name':name,'actual':actual,'expected':expected,'passed':bool(passed)})
    ck('frozen protocol',sha(G/'protocol.json'),frozen['sha256'],sha(G/'protocol.json')==frozen['sha256']);ck('prerun design hash',sha(ROOT/frozen['design_reference']),frozen['design_reference_sha256'],sha(ROOT/frozen['design_reference'])==frozen['design_reference_sha256']);ck('analyzer fingerprint',analysis['analyzer_sha256'],sha(G/'analyze.py'),analysis['analyzer_sha256']==sha(G/'analyze.py'));ck('publication analysis fingerprint',publication['analysis_sha256'],sha(G/'analysis.json'),publication['analysis_sha256']==sha(G/'analysis.json'))
    results=list(G.glob('runs/*/result.json'));ck('formal run count',len(results),8,len(results)==8)
    for f in sorted(results):
        r=read(f);a=dict(np.load(f.parent/'trajectory.npz'));config=read(f.parent/'resolved-config.json');c=next(x for x in p['cases'] if x['id']==r['case']);vname=r['variant'];variant=c['variants'][vname];tag=r['run_id'];dt=p['run']['dt_s'];vel=a['body_qd'][:,0].astype(float);q=a['body_q'][:,0].astype(float);force=np.zeros_like(a['world_contact_force']);torque=np.zeros_like(a['world_contact_torque']);util=[];early_saturated=[];R_errors=[];jtf_errors=[];native_contact_force_errors=[]
        prediction=next(x for x in design['calculations'] if x['shape']==c['shape'] and x['variant']==vname and x['speed']==c['initial_velocity_world'][0 if c['shape']=='box' else 5] and x['slide_coefficient']==variant['body_mu'])
        ck(tag+' completed',r['status'],'completed',r['status']=='completed');ck(tag+' archive integrity',len(r['files_sha256']),True,all(sha(f.parent/key)==val for key,val in r['files_sha256'].items()));ck(tag+' protocol/code identity',True,True,r['protocol_sha256']==frozen['sha256'] and r['runner_sha256']==sha(G/'runner.py'));ck(tag+' start after freeze',r['started_at'],frozen['frozen_at_utc'],r['started_at']>frozen['frozen_at_utc'])
        source=read(f.parent/'installed-source-validation.json');ck(tag+' locked source 809',source['checked_python_files'],809,source['checked_python_files']==809 and not source['mismatches'] and source['actual']==source['expected']);ck(tag+' all finite',True,True,all(np.isfinite(x).all() for x in a.values()));ck(tag+' actual timestep',mx(a['native_timestep']-dt),0,mx(a['native_timestep']-dt)==0);ck(tag+' actual backend',config['backend'],True,config['backend']=={'use_mujoco_cpu':True,'use_mujoco_contacts':True,'update_data_interval':1});ck(tag+' actual cone/impratio',config['options']['cone'],1,config['options']['cone']==1 and config['options']['impratio']==1)
        mask=np.arange(16)[None,:]<a['ncon'][:,None];active=mask&(a['contact_efc_address']>=0);positive_normal=[]
        for n in range(len(a['ncon'])):
            saturations=[];positive=[]
            for k in range(int(a['ncon'][n])):
                w=a['contact_wrench'][n,k];frame=a['contact_frame'][n,k];sign=1 if a['contact_geom'][n,k,1]==config['dynamic_geom'] else -1.;worldf=sign*frame.T@w[:3];worldtau=sign*frame.T@w[3:]+np.cross(a['contact_pos'][n,k]-q[n,:3],worldf);force[n]+=worldf;torque[n]+=worldtau;dim=int(a['contact_dim'][n,k]);adr=int(a['contact_efc_address'][n,k]);positive.append(adr>=0 and w[0]>0)
                if adr>=0 and w[0]>0:
                    cone=float(np.linalg.norm(w[1:dim]/a['contact_friction'][n,k,:dim-1])/w[0]);util.append(cone);saturations.append(.98<=cone<=1.00001)
                    R=a['native_efc_R'][n,adr:adr+dim];friction=a['contact_friction'][n,k];R_errors.append(abs(R[1]-R[0]/config['options']['impratio']))
                    for j in range(1,dim-1):R_errors.append(abs(R[j+1]*friction[j]**2-R[1]*friction[0]**2))
                    native_contact_force_errors.append(mx(a['native_efc_force'][n,adr:adr+dim]-w[:dim]))
            positive_normal.append(any(positive));early_saturated.append(bool(saturations) and all(saturations))
            nefc=int(a['native_nefc'][n]);jtf_errors.append(mx(a['native_efc_J'][n,:nefc].T@a['native_efc_force'][n,:nefc]-a['native_qfrc_constraint'][n]))
        positive_normal=np.array(positive_normal);early_saturated=np.array(early_saturated);ck(tag+' independent world wrench',max(mx(force-a['world_contact_force']),mx(torque-a['world_contact_torque'])),1e-12,max(mx(force-a['world_contact_force']),mx(torque-a['world_contact_torque']))<1e-12)
        ck(tag+' J transpose force',max(jtf_errors),1e-10,max(jtf_errors)<1e-10);ck(tag+' contact/native force',max(native_contact_force_errors),1e-12,max(native_contact_force_errors)<1e-12);ck(tag+' R scaling',max(R_errors),1e-12,max(R_errors)<1e-12)
        impulse=dt*np.cumsum(force+np.array([0,0,-9.81]),axis=0);linear_error=mx(vel[1:,:3]-vel[0,:3]-impulse);step_error=mx(np.diff(vel[:,:3],axis=0)-dt*(force+np.array([0,0,-9.81])));ck(tag+' accumulated linear impulse',linear_error,p['common_criteria']['linear_impulse_balance_max_error_Ns'],linear_error<=p['common_criteria']['linear_impulse_balance_max_error_Ns'])
        anchor=int(round(p['run']['settled_analysis_starts_s']/dt));post=np.arange(len(a['ncon']))>=anchor;active_fraction=float(active[post].any(axis=1).mean());positive_fraction=float(positive_normal[post].mean());full_positive=float(positive_normal.mean());ck(tag+' settled active',active_fraction,p['common_criteria']['settled_contact_present_fraction_min'],active_fraction>=p['common_criteria']['settled_contact_present_fraction_min']);ck(tag+' settled positive force',positive_fraction,p['common_criteria']['settled_positive_normal_force_fraction_min'],positive_fraction>=p['common_criteria']['settled_positive_normal_force_fraction_min']);ck(tag+' reported full 100% bearing',full_positive,1,full_positive==1)
        firstN=float(force[0,2]);qp_error=abs(firstN-prediction['normal_total_N']);ck(tag+' pre-run QP prediction',qp_error,1e-5,qp_error<1e-5);ck(tag+' first N below mg',firstN,9.81,firstN<9.81)
        maxutil=max(util);minutil=min(util);ck(tag+' cone feasible',maxutil,1.00001,maxutil<=1.00001);early=(a['t'][:-1]<.02-1e-12);early_count=int(early_saturated[early].sum())
        # This is a supplement diagnostic, never retroactively a frozen physical gate.
